class Solution {
public:
    int maxEqualRowsAfterFlips(vector<vector<int>>& matrix) {
        unordered_map<string, int> count;
        int m = matrix.size();
        int n = matrix[0].size();
        int ans = 0;
        for (int i = 0; i < m; i++) {
            string key(n, '0');
            int flip = matrix[i][0];
            for (int j = 0; j < n; j++) {
                key[j] = '0' + (matrix[i][j] ^ flip);
            }
            count[key]++;
            ans = max(ans, count[key]);
        }
        return ans;
    }
};
